// Toutes les langues disponibles pour l'autocomplétion (dédupliquées)
export const ALL_LANGUAGES = PHRASES.reduce<{ language: string; flag: string; languageCode: string }[]>(
  (acc, p) => {
    if (!acc.some((l) => l.language === p.language)) {
      acc.push({ language: p.language, flag: p.flag, languageCode: p.languageCode });
    }
    return acc;
  },
  []
);

// Mélange un tableau (algorithme Fisher-Yates)
function shuffle<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// File mélangée au niveau du module : garantit que toutes les phrases sont vues
// avant qu'une répétition puisse se produire. Persiste pendant toute la session.
let phraseQueue: Phrase[] = [];

export function getNextPhrase(): Phrase {
  if (phraseQueue.length === 0) {
    phraseQueue = shuffle(PHRASES);
  }
  return phraseQueue.pop()!;
}
